/* Return NULL if failed */
Spacegroup *spa_search_spacegroup(Primitive const *primitive,
                                  int const hall_number, double const symprec,
                                  double const angle_tolerance) {
    Spacegroup *spacegroup;
    Symmetry *symmetry;
    int candidate[1];

    debug_print("search_spacegroup (tolerance = %f):\n", symprec);

    symmetry = NULL;
    spacegroup = NULL;

    if ((symmetry = sym_get_operation(primitive->cell, symprec,
                                      angle_tolerance)) == NULL) {
        return NULL;
    }

    if (hall_number != 0) {
        candidate[0] = hall_number;
    }

    if (hall_number) {
        spacegroup = search_spacegroup_with_symmetry(
            primitive, candidate, 1, symmetry, symprec, angle_tolerance);
    } else if (primitive->cell->aperiodic_axis == -1) {
        spacegroup = search_spacegroup_with_symmetry(
            primitive, spacegroup_to_hall_number, 230, symmetry, symprec,
            angle_tolerance);
    } else {
        spacegroup = search_spacegroup_with_symmetry(
            primitive, layer_group_to_hall_number, 116, symmetry, symprec,
            angle_tolerance);
    };

    sym_free_symmetry(symmetry);
    symmetry = NULL;

    return spacegroup;
}

/* Return NULL if failed */
/* Assume symmetry is transformed in primitive cell. */
Spacegroup *spa_search_spacegroup_with_symmetry(Symmetry const *symmetry,
                                                double const prim_lat[3][3],
                                                double const symprec) {
    int i;
    Spacegroup *spacegroup;
    Primitive *primitive;

    spacegroup = NULL;

    if ((primitive = prm_alloc_primitive(1)) == NULL) {
        return 0;
    }
    if ((primitive->cell = cel_alloc_cell(1, NOSPIN)) == NULL) {
        return 0;
    }
    mat_copy_matrix_d3(primitive->cell->lattice, prim_lat);
    for (i = 0; i < 3; i++) {
        primitive->cell->position[0][i] = 0;
    }
    spacegroup = search_spacegroup_with_symmetry(
        primitive, spacegroup_to_hall_number, 230, symmetry, symprec, -1.0);
    prm_free_primitive(primitive);
    primitive = NULL;

    return spacegroup;
}

/* Return NULL if failed */
Cell *spa_transform_to_primitive(int *mapping_table, Cell const *cell,
                                 double const trans_mat[3][3],
                                 Centering const centering,
                                 double const symprec) {
    double tmat[3][3], tmat_inv[3][3], prim_lat[3][3];
    Cell *primitive;

    primitive = NULL;

    if (!mat_inverse_matrix_d3(tmat_inv, trans_mat, symprec)) {
        goto err;
    }

    switch (centering) {
        case PRIMITIVE:
            mat_copy_matrix_d3(tmat, tmat_inv);
            break;
        case A_FACE:
            mat_multiply_matrix_d3(tmat, tmat_inv, A_mat);
            break;
        case C_FACE:
            mat_multiply_matrix_d3(tmat, tmat_inv, C_mat);
            break;
        case FACE:
            mat_multiply_matrix_d3(tmat, tmat_inv, F_mat);
            break;
        case BODY:
            mat_multiply_matrix_d3(tmat, tmat_inv, I_mat);
            break;
        case R_CENTER:
            mat_multiply_matrix_d3(tmat, tmat_inv, R_mat);
            break;
        default:
            goto err;
    }

    mat_multiply_matrix_d3(prim_lat, cell->lattice, tmat);
    if ((primitive = cel_trim_cell(mapping_table, prim_lat, cell, symprec)) ==
        NULL) {
        warning_print("spglib: cel_trim_cell failed.\n");
    }

    return primitive;

err:
    return NULL;
}

