static Cell *get_primitive_cell(int *mapping_table, Cell const *cell,
                                VecDBL const *pure_trans, double const symprec,
                                double const angle_tolerance) {
    int multi;
    double prim_lattice[3][3];
    Cell *primitive_cell;

    debug_print("get_primitive_cell:\n");

    primitive_cell = NULL;

    /* Primitive lattice vectors are searched. */
    /* To be consistent, sometimes tolerance is decreased iteratively. */
    /* The decreased tolerance is stored in 'static double tolerance'. */
    multi = get_primitive_lattice_vectors(prim_lattice, cell, pure_trans,
                                          symprec, angle_tolerance);
    if (!multi) {
        goto not_found;
    }

    /* Fit atoms into new primitive cell */
    if ((primitive_cell = cel_trim_cell(mapping_table, prim_lattice, cell,
                                        symprec)) == NULL) {
        goto not_found;
    }

    /* found */
    return primitive_cell;

not_found:
    debug_print("spglib: Primitive cell could not be found\n");
    return NULL;
}

/* Return 0 if failed */
static int get_primitive_lattice_vectors(double prim_lattice[3][3],
                                         Cell const *cell,
                                         VecDBL const *pure_trans,
                                         double const symprec,
                                         double const angle_tolerance) {
    int i, multi, attempt;
    double tolerance;
    VecDBL *vectors, *pure_trans_reduced, *tmp_vec;

    vectors = NULL;
    pure_trans_reduced = NULL;
    tmp_vec = NULL;

    tolerance = symprec;

    if ((pure_trans_reduced = mat_alloc_VecDBL(pure_trans->size)) == NULL) {
        goto fail;
    }

    for (i = 0; i < pure_trans->size; i++) {
        mat_copy_vector_d3(pure_trans_reduced->vec[i], pure_trans->vec[i]);
    }

    for (attempt = 0; attempt < NUM_ATTEMPT; attempt++) {
        multi = pure_trans_reduced->size;

        if ((vectors = get_translation_candidates(pure_trans_reduced)) ==
            NULL) {
            mat_free_VecDBL(pure_trans_reduced);
            pure_trans_reduced = NULL;
            goto fail;
        }

        /* Lattice of primitive cell is found among pure translation vectors */
        if (find_primitive_lattice_vectors(prim_lattice, vectors, cell,
                                           tolerance)) {
            mat_free_VecDBL(vectors);
            vectors = NULL;
            mat_free_VecDBL(pure_trans_reduced);
            pure_trans_reduced = NULL;

            if ((cell->aperiodic_axis == -1 &&
                 !del_delaunay_reduce(prim_lattice, prim_lattice, symprec)) ||
                (cell->aperiodic_axis != -1 &&
                 !del_layer_delaunay_reduce(prim_lattice, prim_lattice,
                                            cell->aperiodic_axis, symprec))) {
                goto fail;
            }

            goto found;

        } else {
            if ((tmp_vec = mat_alloc_VecDBL(multi)) == NULL) {
                mat_free_VecDBL(vectors);
                vectors = NULL;
                mat_free_VecDBL(pure_trans_reduced);
                pure_trans_reduced = NULL;
                goto fail;
            }

            for (i = 0; i < multi; i++) {
                mat_copy_vector_d3(tmp_vec->vec[i], pure_trans_reduced->vec[i]);
            }
            mat_free_VecDBL(pure_trans_reduced);
            pure_trans_reduced = NULL;

            pure_trans_reduced = sym_reduce_pure_translation(
                cell, tmp_vec, tolerance, angle_tolerance);

            mat_free_VecDBL(tmp_vec);
            tmp_vec = NULL;
            mat_free_VecDBL(vectors);
            vectors = NULL;

            if (pure_trans_reduced == NULL) {
                goto fail;
            }

            debug_print("spglib: Tolerance is reduced to %f (%d), ", tolerance,
                        attempt);
            debug_print("num_pure_trans = %d\n", pure_trans_reduced->size);

            tolerance *= REDUCE_RATE;
        }
    }

    mat_free_VecDBL(pure_trans_reduced);
    pure_trans_reduced = NULL;

fail:
    return 0;

found:
    return multi;
}

/* Return 0 if failed */
static int find_primitive_lattice_vectors(double prim_lattice[3][3],
                                          VecDBL const *vectors,
                                          Cell const *cell,
                                          double const symprec) {
    int i, j, k, size, aperiodic_axis;
    double initial_volume, volume;
    double relative_lattice[3][3], min_vectors[3][3], tmp_lattice[3][3];
    double inv_mat_dbl[3][3];
    int inv_mat_int[3][3];

    debug_print("find_primitive_lattice_vectors:\n");

    size = vectors->size;
    initial_volume = mat_Dabs(mat_get_determinant_d3(cell->lattice));
    aperiodic_axis = cell->aperiodic_axis;

    /* check volumes of all possible lattices, find smallest volume */
    if (aperiodic_axis == -1) {
        for (i = 0; i < size; i++) {
            for (j = i + 1; j < size; j++) {
                for (k = j + 1; k < size; k++) {
                    mat_multiply_matrix_vector_d3(tmp_lattice[0], cell->lattice,
                                                  vectors->vec[i]);
                    mat_multiply_matrix_vector_d3(tmp_lattice[1], cell->lattice,
                                                  vectors->vec[j]);
                    mat_multiply_matrix_vector_d3(tmp_lattice[2], cell->lattice,
                                                  vectors->vec[k]);
                    volume = mat_Dabs(mat_get_determinant_d3(tmp_lattice));
                    if (volume > symprec) {
                        if (mat_Nint(initial_volume / volume) == size - 2) {
                            mat_copy_vector_d3(min_vectors[0], vectors->vec[i]);
                            mat_copy_vector_d3(min_vectors[1], vectors->vec[j]);
                            mat_copy_vector_d3(min_vectors[2], vectors->vec[k]);
                            goto ret;
                        }
                    }
                }
            }
        }
    } else {
        /* for layer, first move aperiodic axis to c */
        k = size + aperiodic_axis - 3;

        for (i = 0; i < size; i++) {
            for (j = i + 1; j < size; j++) {
                if (i != k && j != k) {
                    mat_multiply_matrix_vector_d3(tmp_lattice[0], cell->lattice,
                                                  vectors->vec[i]);
                    mat_multiply_matrix_vector_d3(tmp_lattice[1], cell->lattice,
                                                  vectors->vec[j]);
                    mat_multiply_matrix_vector_d3(tmp_lattice[2], cell->lattice,
                                                  vectors->vec[k]);
                    volume = mat_Dabs(mat_get_determinant_d3(tmp_lattice));
                    if (volume > symprec) {
                        if (mat_Nint(initial_volume / volume) == size - 2) {
                            mat_copy_vector_d3(min_vectors[0], vectors->vec[i]);
                            mat_copy_vector_d3(min_vectors[1], vectors->vec[j]);
                            /* move aperiodic axis back */
                            if (aperiodic_axis == 2) {
                                mat_copy_vector_d3(min_vectors[2],
                                                   vectors->vec[k]);
                            } else {
                                mat_copy_vector_d3(min_vectors[2],
                                                   min_vectors[aperiodic_axis]);
                                mat_copy_vector_d3(min_vectors[aperiodic_axis],
                                                   vectors->vec[k]);
                            }
                            goto ret;
                        }
                    }
                }
            }
        }
    }

    /* Not found */
    debug_print("spglib: Primitive lattice vectors could not be found\n");
    return 0;

    /* Found */
ret:
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            relative_lattice[j][i] = min_vectors[i][j];
        }
    }

    mat_inverse_matrix_d3(inv_mat_dbl, relative_lattice, 0);
    mat_cast_matrix_3d_to_3i(inv_mat_int, inv_mat_dbl);
    if (abs(mat_get_determinant_i3(inv_mat_int)) == size - 2) {
        mat_cast_matrix_3i_to_3d(inv_mat_dbl, inv_mat_int);
        mat_inverse_matrix_d3(relative_lattice, inv_mat_dbl, 0);
    } else {
        warning_print("spglib: Primitive lattice cleaning is incomplete\n");
    }
    mat_multiply_matrix_d3(prim_lattice, cell->lattice, relative_lattice);

    return 1;
}

static VecDBL *get_translation_candidates(VecDBL const *pure_trans) {
    int i, j, multi;
    VecDBL *vectors;

    vectors = NULL;
    multi = pure_trans->size;

    if ((vectors = mat_alloc_VecDBL(multi + 2)) == NULL) {
        return NULL;
    }

    /* store pure translations in original cell */
    /* as trial primitive lattice vectors */
    for (i = 0; i < multi - 1; i++) {
        mat_copy_vector_d3(vectors->vec[i], pure_trans->vec[i + 1]);
    }

    /* store lattice translations of original cell */
    /* as trial primitive lattice vectors */
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            if (i == j) {
                vectors->vec[i + multi - 1][j] = 1;
            } else {
                vectors->vec[i + multi - 1][j] = 0;
            }
        }
    }

    return vectors;
}

static VecDBL *collect_pure_translations(Symmetry const *symmetry) {
    int i, num_pure_trans;
    VecDBL *pure_trans;
    VecDBL *ret_pure_trans;
    static int identity[3][3] = {{1, 0, 0}, {0, 1, 0}, {0, 0, 1}};
    num_pure_trans = 0;
    pure_trans = NULL;
    ret_pure_trans = NULL;

    if ((pure_trans = mat_alloc_VecDBL(symmetry->size)) == NULL) {
        return NULL;
    }

    for (i = 0; i < symmetry->size; i++) {
        if (mat_check_identity_matrix_i3(symmetry->rot[i], identity)) {
            mat_copy_vector_d3(pure_trans->vec[num_pure_trans],
                               symmetry->trans[i]);
            num_pure_trans++;
        }
    }

    if ((ret_pure_trans = mat_alloc_VecDBL(num_pure_trans)) == NULL) {
        mat_free_VecDBL(pure_trans);
        pure_trans = NULL;
        return NULL;
    }

    for (i = 0; i < num_pure_trans; i++) {
        mat_copy_vector_d3(ret_pure_trans->vec[i], pure_trans->vec[i]);
    }

    mat_free_VecDBL(pure_trans);
    pure_trans = NULL;

    return ret_pure_trans;
}

static int get_primitive_in_translation_space(double t_mat_inv[3][3],
                                              VecDBL const *pure_trans,
                                              int const symmetry_size,
                                              double const symprec) {
    int i, j, primsym_size;
    Primitive *primitive;
    Cell *cell;

    cell = NULL;
    primitive = NULL;

    if ((cell = cel_alloc_cell(pure_trans->size, NOSPIN)) == NULL) {
        return 0;
    }

    primsym_size = symmetry_size / pure_trans->size;
    if (symmetry_size != primsym_size * pure_trans->size) {
        cel_free_cell(cell);
        cell = NULL;
        return 0;
    }

    for (i = 0; i < pure_trans->size; i++) {
        cell->types[i] = 1;
        for (j = 0; j < 3; j++) {
            cell->position[i][j] = pure_trans->vec[i][j];
        }
    }

    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            if (i == j) {
                cell->lattice[i][j] = 1;
            } else {
                cell->lattice[i][j] = 0;
            }
        }
    }

    primitive = get_primitive(cell, symprec, -1.0);
    cel_free_cell(cell);
    cell = NULL;

    if (primitive == NULL) {
        return 0;
    }

    if (primitive->cell->size != 1) {
        prm_free_primitive(primitive);
        primitive = NULL;
        return 0;
    }

    mat_copy_matrix_d3(t_mat_inv, primitive->cell->lattice);
    prm_free_primitive(primitive);
    primitive = NULL;

    return 1;
}

static Symmetry *collect_primitive_symmetry(Symmetry const *symmetry,
                                            int const primsym_size) {
    int i, j, num_psym, is_found;
    Symmetry *prim_symmetry;

    prim_symmetry = NULL;

    prim_symmetry = sym_alloc_symmetry(primsym_size);
    num_psym = 1;
    mat_copy_matrix_i3(prim_symmetry->rot[0], symmetry->rot[0]);
    mat_copy_vector_d3(prim_symmetry->trans[0], symmetry->trans[0]);
    for (i = 1; i < symmetry->size; i++) {
        is_found = 1;
        for (j = 0; j < num_psym; j++) {
            if (mat_check_identity_matrix_i3(prim_symmetry->rot[j],
                                             symmetry->rot[i])) {
                is_found = 0;
                break;
            }
        }
        if (is_found) {
            if (num_psym == primsym_size) {
                sym_free_symmetry(prim_symmetry);
                prim_symmetry = NULL;
                break;
            }
            mat_copy_matrix_i3(prim_symmetry->rot[num_psym], symmetry->rot[i]);
            mat_copy_vector_d3(prim_symmetry->trans[num_psym],
                               symmetry->trans[i]);
            num_psym++;
        }
    }

    if (prim_symmetry == NULL) {
        return NULL;
    }

    if (num_psym != primsym_size) {
        sym_free_symmetry(prim_symmetry);
        prim_symmetry = NULL;
        return NULL;
    }

    return prim_symmetry;
}

Spacegroup *spa_search_spacegroup(Primitive const *primitive,
                                  int const hall_number, double const symprec,
                                  double const angle_tolerance) {
    Spacegroup *spacegroup;
    Symmetry *symmetry;
    int candidate[1];

    debug_print("search_spacegroup (tolerance = %f):\n", symprec);

    symmetry = NULL;
    spacegroup = NULL;

    if ((symmetry = sym_get_operation(primitive->cell, symprec,
                                      angle_tolerance)) == NULL) {
        return NULL;
    }

    if (hall_number != 0) {
        candidate[0] = hall_number;
    }

    if (hall_number) {
        spacegroup = search_spacegroup_with_symmetry(
            primitive, candidate, 1, symmetry, symprec, angle_tolerance);
    } else if (primitive->cell->aperiodic_axis == -1) {
        spacegroup = search_spacegroup_with_symmetry(
            primitive, spacegroup_to_hall_number, 230, symmetry, symprec,
            angle_tolerance);
    } else {
        spacegroup = search_spacegroup_with_symmetry(
            primitive, layer_group_to_hall_number, 116, symmetry, symprec,
            angle_tolerance);
    };

    sym_free_symmetry(symmetry);
    symmetry = NULL;

    return spacegroup;
}

/* Return NULL if failed */
/* Assume symmetry is transformed in primitive cell. */
Spacegroup *spa_search_spacegroup_with_symmetry(Symmetry const *symmetry,
                                                double const prim_lat[3][3],
                                                double const symprec) {
    int i;
    Spacegroup *spacegroup;
    Primitive *primitive;

    spacegroup = NULL;

    if ((primitive = prm_alloc_primitive(1)) == NULL) {
        return 0;
    }
    if ((primitive->cell = cel_alloc_cell(1, NOSPIN)) == NULL) {
        return 0;
    }
    mat_copy_matrix_d3(primitive->cell->lattice, prim_lat);
    for (i = 0; i < 3; i++) {
        primitive->cell->position[0][i] = 0;
    }
    spacegroup = search_spacegroup_with_symmetry(
        primitive, spacegroup_to_hall_number, 230, symmetry, symprec, -1.0);
    prm_free_primitive(primitive);
    primitive = NULL;

    return spacegroup;
}

/* Return NULL if failed */
static Spacegroup *search_spacegroup_with_symmetry(
    Primitive const *primitive, int const candidates[],
    int const num_candidates, Symmetry const *symmetry, double const symprec,
    double const angle_tolerance) {
    int hall_number;
    double conv_lattice[3][3];
    double origin_shift[3];
    Spacegroup *spacegroup;
    PointSymmetry pointsym;

    debug_print("search_spacegroup (tolerance = %f):\n", symprec);

    spacegroup = NULL;
    origin_shift[0] = 0;
    origin_shift[1] = 0;
    origin_shift[2] = 0;

    pointsym = ptg_get_pointsymmetry(symmetry->rot, symmetry->size);
    if (pointsym.size < symmetry->size) {
        info_print("spglib: Point symmetry of primitive cell is broken.\n");
        return NULL;
    }

    hall_number = iterative_search_hall_number(
        origin_shift, conv_lattice, candidates, num_candidates, primitive,
        symmetry, symprec, angle_tolerance);
    if (hall_number == 0) {
        return NULL;
    }

    spacegroup = get_spacegroup(hall_number, origin_shift, conv_lattice);

    return spacegroup;
}

/* Return spacegroup.number = 0 if failed */
static Spacegroup *get_spacegroup(int const hall_number,
                                  double const origin_shift[3],
                                  double const conv_lattice[3][3]) {
    Spacegroup *spacegroup;
    SpacegroupType spacegroup_type;

    spacegroup = NULL;

    if ((spacegroup = (Spacegroup *)malloc(sizeof(Spacegroup))) == NULL) {
        warning_memory("spacegroup");
        return NULL;
    }

    if (-117 < hall_number && hall_number < 531 && hall_number != 0) {
        spacegroup_type = spgdb_get_spacegroup_type(hall_number);
        mat_copy_matrix_d3(spacegroup->bravais_lattice, conv_lattice);
        mat_copy_vector_d3(spacegroup->origin_shift, origin_shift);
        spacegroup->number = spacegroup_type.number;
        spacegroup->hall_number = hall_number;
        spacegroup->pointgroup_number = spacegroup_type.pointgroup_number;
        memcpy(spacegroup->schoenflies, spacegroup_type.schoenflies, 7);
        memcpy(spacegroup->hall_symbol, spacegroup_type.hall_symbol, 17);
        memcpy(spacegroup->international, spacegroup_type.international, 32);
        memcpy(spacegroup->international_long,
               spacegroup_type.international_full, 20);
        memcpy(spacegroup->international_short,
               spacegroup_type.international_short, 11);
        memcpy(spacegroup->choice, spacegroup_type.choice, 6);
    }

    return spacegroup;
}

/* Return 0 if failed */
static int iterative_search_hall_number(
    double origin_shift[3], double conv_lattice[3][3], int const candidates[],
    int const num_candidates, Primitive const *primitive,
    Symmetry const *symmetry, double const symprec,
    double const angle_tolerance) {
    int attempt, hall_number;
    double tolerance;
    Symmetry *sym_reduced;

    debug_print("iterative_search_hall_number:\n");

    hall_number = 0;
    sym_reduced = NULL;

    hall_number =
        search_hall_number(origin_shift, conv_lattice, candidates,
                           num_candidates, primitive, symmetry, symprec);

    if (hall_number != 0) {
        goto ret;
    }

    tolerance = symprec;
    for (attempt = 0; attempt < NUM_ATTEMPT; attempt++) {
        debug_print("spglib: Attempt %d tolerance = %e failed", attempt,
                    tolerance);

        tolerance *= REDUCE_RATE;
        sym_reduced = sym_reduce_operation(primitive->cell, symmetry, tolerance,
                                           angle_tolerance);
        if (sym_reduced) {
            hall_number = search_hall_number(origin_shift, conv_lattice,
                                             candidates, num_candidates,
                                             primitive, sym_reduced, symprec);
            sym_free_symmetry(sym_reduced);
            sym_reduced = NULL;
        }
        if (hall_number != 0) {
            break;
        }
    }

ret:
    return hall_number;
}

/* Return 0 if failed */
static int search_hall_number(double origin_shift[3], double conv_lattice[3][3],
                              int const candidates[], int const num_candidates,
                              Primitive const *primitive,
                              Symmetry const *symmetry, double const symprec) {
    int i, hall_number, aperiodic_axis;
    Centering centering;
    Pointgroup pointgroup;
    Symmetry *conv_symmetry;
    int tmat_int[3][3];
    double correction_mat[3][3], tmat[3][3], conv_lattice_tmp[3][3];

    debug_print("search_hall_number:\n");

    hall_number = 0;
    conv_symmetry = NULL;

    aperiodic_axis = primitive->cell->aperiodic_axis;

    /* primitive->cell->lattice is set right handed. */
    /* tmat_int is set right handed. */

    /* For rhombohedral system, basis vectors for hP */
    /* (hexagonal lattice basis) are provided by tmat_int, */
    /* but may be either obverse or reverse setting. */
    pointgroup = ptg_get_transformation_matrix(tmat_int, symmetry->rot,
                                               symmetry->size, aperiodic_axis);

    debug_print("initial transformation matrix\n");
    debug_print_matrix_i3(tmat_int);

    if (pointgroup.number == 0) {
        goto err;
    }

    /* For LAUE1 and LAUE2M, update tmat_int by making smallest lattice */
    if (pointgroup.laue == LAUE1 || pointgroup.laue == LAUE2M) {
        mat_multiply_matrix_di3(conv_lattice_tmp, primitive->cell->lattice,
                                tmat_int);

        if (pointgroup.laue == LAUE1) {
            if (!change_basis_tricli(tmat_int, conv_lattice_tmp,
                                     primitive->cell->lattice, symprec,
                                     aperiodic_axis)) {
                goto err;
            }
        }

        /* The angle between non-unique axes may be acute or non-acute. */
        if (pointgroup.laue == LAUE2M) {
            if (!change_basis_monocli(tmat_int, conv_lattice_tmp,
                                      primitive->cell->lattice, symprec,
                                      aperiodic_axis)) {
                goto err;
            }
        }
    }

    /* For rhombohedral system, correction matrix to hR */
    /* (a=b=c primitive lattice basis) is returned judging */
    /* either obverse or reverse setting. centering=R_CENTER. */
    if ((centering = get_centering(correction_mat, tmat_int,
                                   pointgroup.laue)) == CENTERING_ERROR) {
        goto err;
    }

    mat_multiply_matrix_id3(tmat, tmat_int, correction_mat);
    mat_multiply_matrix_d3(conv_lattice, primitive->cell->lattice, tmat);

    debug_print("transformation matrix\n");
    debug_print_matrix_d3(tmat);

    /* For rhombohedral system, symmetry for a=b=c primitive lattice */
    /* basis is returned although centering == R_CENTER. */
    if ((conv_symmetry = get_initial_conventional_symmetry(centering, tmat,
                                                           symmetry)) == NULL) {
        goto err;
    }

    for (i = 0; i < num_candidates; i++) {
        /* Check if hall_number is that of rhombohedral. */
        if (match_hall_symbol_db(
                origin_shift, conv_lattice, /* <-- modified only matched */
                primitive->orig_lattice, candidates[i], pointgroup.number,
                pointgroup.holohedry, centering, conv_symmetry, symprec)) {
            debug_print("origin shift\n");
            debug_print_vector_d3(origin_shift);

            hall_number = candidates[i];
            break;
        }
    }

    sym_free_symmetry(conv_symmetry);
    conv_symmetry = NULL;

    return hall_number;

err:
    return 0;
}

// Perform Niggli cell reduction for Triclinic. Return 0 if failed.
static int change_basis_tricli(int tmat_int[3][3],
                               double const conv_lattice[3][3],
                               double const primitive_lattice[3][3],
                               double const symprec, int const aperiodic_axis) {
    int i, j;
    double niggli_cell[9];
    double smallest_lattice[3][3], inv_lattice[3][3], tmat[3][3];

    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            niggli_cell[i * 3 + j] = conv_lattice[i][j];
        }
    }

    if (!niggli_reduce(niggli_cell, symprec * symprec, aperiodic_axis)) {
        return 0;
    }

    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            smallest_lattice[i][j] = niggli_cell[i * 3 + j];
        }
    }
    if (mat_get_determinant_d3(smallest_lattice) < 0) {
        for (i = 0; i < 3; i++) {
            for (j = 0; j < 3; j++) {
                smallest_lattice[i][j] = -smallest_lattice[i][j];
            }
        }
    }
    mat_inverse_matrix_d3(inv_lattice, primitive_lattice, 0);
    mat_multiply_matrix_d3(tmat, inv_lattice, smallest_lattice);
    mat_cast_matrix_3d_to_3i(tmat_int, tmat);

    return 1;
}

/* Monoclinic: choose shortest a, c lattice vectors (|a| < |c|) */
/* Return 0 if failed */
static int change_basis_monocli(int tmat_int[3][3],
                                double const conv_lattice[3][3],
                                double const primitive_lattice[3][3],
                                double const symprec,
                                int const aperiodic_axis_prim) {
    double smallest_lattice[3][3], inv_lattice[3][3], tmat[3][3];
    int i, aperiodic_axis_conv, unique_axis;

    /* Unique axis of 3D monoclinic crystal system is b */
    /* For layer with 2D op/oc lattice, unique axis is a */
    if (aperiodic_axis_prim == -1) {
        aperiodic_axis_conv = -1;
        unique_axis = 1;
    } else {
        for (i = 0; i < 3; i++) {
            if (tmat_int[aperiodic_axis_prim][i] != 0) {
                aperiodic_axis_conv = i;
            }
        }
        unique_axis = 0;
    }

    if (!del_layer_delaunay_reduce_2D(smallest_lattice, conv_lattice,
                                      unique_axis, aperiodic_axis_conv,
                                      symprec)) {
        return 0;
    }

    /* For layer with 2D mp lattice, move the unique axis to c */
    if (aperiodic_axis_conv == 0) {
        mat_multiply_matrix_d3(smallest_lattice, smallest_lattice,
                               change_of_basis_monocli[2]);
    }

    mat_inverse_matrix_d3(inv_lattice, primitive_lattice, 0);
    mat_multiply_matrix_d3(tmat, inv_lattice, smallest_lattice);
    mat_cast_matrix_3d_to_3i(tmat_int, tmat);
    return 1;
}

/* Return NULL if failed */
static Symmetry *get_initial_conventional_symmetry(Centering const centering,
                                                   double const tmat[3][3],
                                                   Symmetry const *symmetry) {
    Symmetry *conv_symmetry;

    debug_print("get_initial_conventional_symmetry\n");

    conv_symmetry = NULL;

    if (centering == R_CENTER) {
        /* hP for rhombohedral */
        conv_symmetry = get_conventional_symmetry(tmat, PRIMITIVE, symmetry);
    } else {
        conv_symmetry = get_conventional_symmetry(tmat, centering, symmetry);
    }

    return conv_symmetry;
}

