/* Return NULL if failed */
Symmetry *sym_alloc_symmetry(int const size) {
    Symmetry *symmetry;

    symmetry = NULL;

    if (size < 1) {
        return NULL;
    }

    if ((symmetry = (Symmetry *)malloc(sizeof(Symmetry))) == NULL) {
        warning_memory("symmetry");
        return NULL;
    }

    symmetry->size = size;
    symmetry->rot = NULL;
    symmetry->trans = NULL;

    if ((symmetry->rot = (int (*)[3][3])malloc(sizeof(int[3][3]) * size)) ==
        NULL) {
        warning_memory("symmetry->rot");
        free(symmetry);
        symmetry = NULL;
        return NULL;
    }
    if ((symmetry->trans = (double (*)[3])malloc(sizeof(double[3]) * size)) ==
        NULL) {
        warning_memory("symmetry->trans");
        free(symmetry->rot);
        symmetry->rot = NULL;
        free(symmetry);
        symmetry = NULL;
        return NULL;
    }

    return symmetry;
}

void sym_free_symmetry(Symmetry *symmetry) {
    if (symmetry->size > 0) {
        free(symmetry->rot);
        symmetry->rot = NULL;
        free(symmetry->trans);
        symmetry->trans = NULL;
    }
    free(symmetry);
}

