static int find_hall_symbol(double origin_shift[3],
                            double const bravais_lattice[3][3],
                            int const hall_number, Centering const centering,
                            Symmetry const *symmetry, double const symprec) {
    double primitive_lattice[3][3];

    switch (centering) {
        case PRIMITIVE:
            mat_copy_matrix_d3(primitive_lattice, bravais_lattice);
            break;
        case BODY:
            mat_multiply_matrix_d3(primitive_lattice, bravais_lattice,
                                   M_bcc_inv);
            break;
        case FACE:
            mat_multiply_matrix_d3(primitive_lattice, bravais_lattice,
                                   M_fcc_inv);
            break;
        case A_FACE:
            mat_multiply_matrix_d3(primitive_lattice, bravais_lattice,
                                   M_ac_inv);
            break;
        case B_FACE:
            mat_multiply_matrix_d3(primitive_lattice, bravais_lattice,
                                   M_bc_inv);
            break;
        case C_FACE:
            mat_multiply_matrix_d3(primitive_lattice, bravais_lattice,
                                   M_cc_inv);
            break;
        case R_CENTER:
            mat_multiply_matrix_d3(primitive_lattice, bravais_lattice,
                                   M_rc_inv);
            break;
        default:
            break;
    }

    /* CUBIC IT: 195-230, Hall: 489-530 */
    if (489 <= hall_number && hall_number <= 530) {
        if (is_hall_symbol_cubic(origin_shift, hall_number, primitive_lattice,
                                 symmetry, centering, symprec)) {
            goto found;
        }
        return 0;
    }

    /* HEXA, ITA: 168-194, Hall: 462-488; ITE: 73-80, Layer Hall: 109-116 */
    if ((462 <= hall_number && hall_number <= 488) ||
        (-116 <= hall_number && hall_number <= -109)) {
        if (is_hall_symbol_hexa(origin_shift, hall_number, primitive_lattice,
                                symmetry, symprec)) {
            goto found;
        }
        return 0;
    }

    /* TRIGO, ITA: 143-167, Hall: 430-461; ITE: 65-73, Layer Hall: 101-108 */
    if ((430 <= hall_number && hall_number <= 461) ||
        (-108 <= hall_number && hall_number <= -101)) {
        if (hall_number == 433 || hall_number == 434 || hall_number == 436 ||
            hall_number == 437 || hall_number == 444 || hall_number == 445 ||
            hall_number == 450 || hall_number == 451 || hall_number == 452 ||
            hall_number == 453 || hall_number == 458 || hall_number == 459 ||
            hall_number == 460 || hall_number == 461) {
            if (is_hall_symbol_rhombo(origin_shift, hall_number,
                                      primitive_lattice, symmetry, symprec)) {
                goto found;
            }
        } else {
            if (is_hall_symbol_trigonal(origin_shift, hall_number,
                                        primitive_lattice, symmetry, symprec)) {
                goto found;
            }
        }
        return 0;
    }

    /* TETRA, ITA: 75-142, Hall: 349-429; ITE: 49-64, Layer Hall: 82-100 */
    if ((349 <= hall_number && hall_number <= 429) ||
        (-100 <= hall_number && hall_number <= -82)) {
        if (is_hall_symbol_tetra(origin_shift, hall_number, primitive_lattice,
                                 symmetry, centering, symprec)) {
            goto found;
        }
        return 0;
    }

    /* ORTHO, ITA: 16-74, Hall: 108-348; ITE: 19-48, Layer Hall: 34-81 */
    if ((108 <= hall_number && hall_number <= 348) ||
        (-81 <= hall_number && hall_number <= -34)) {
        if (is_hall_symbol_ortho(origin_shift, hall_number, primitive_lattice,
                                 symmetry, centering, symprec)) {
            goto found;
        }
        return 0;
    }

    /* MONOCLI, ITA: 3-15, Hall: 3-107; ITE: 3-18, Layer Hall: 3-33 */
    if ((3 <= hall_number && hall_number <= 107) ||
        (-33 <= hall_number && hall_number <= -3)) {
        if (is_hall_symbol_monocli(origin_shift, hall_number, primitive_lattice,
                                   symmetry, centering, symprec)) {
            goto found;
        }
        return 0;
    }

    /* TRICLI, ITA: 1-2, Hall: 1-2; ITE: 1-2, Layer Hall: 1-2 */
    if (-2 <= hall_number && hall_number <= 2 && hall_number != 0) {
        if (is_hall_symbol_tricli(origin_shift, hall_number, primitive_lattice,
                                  symmetry, symprec)) {
            goto found;
        }
        return 0;
    }

    return 0;

found:
    switch (centering) {
        case PRIMITIVE:
            break;
        case BODY:
            mat_multiply_matrix_vector_d3(origin_shift, M_bcc_inv,
                                          origin_shift);
            break;
        case FACE:
            mat_multiply_matrix_vector_d3(origin_shift, M_fcc_inv,
                                          origin_shift);
            break;
        case A_FACE:
            mat_multiply_matrix_vector_d3(origin_shift, M_ac_inv, origin_shift);
            break;
        case B_FACE:
            mat_multiply_matrix_vector_d3(origin_shift, M_bc_inv, origin_shift);
            break;
        case C_FACE:
            mat_multiply_matrix_vector_d3(origin_shift, M_cc_inv, origin_shift);
            break;
        case R_CENTER:
            mat_multiply_matrix_vector_d3(origin_shift, M_rc_inv, origin_shift);
            break;
        default:
            break;
    }
    return 1;
}

static int is_hall_symbol_cubic(double shift[3], int const hall_number,
                                double const primitive_lattice[3][3],
                                Symmetry const *symmetry,
                                Centering const centering,
                                double const symprec) {
    int i;

    for (i = 0; i < 10; i++) {
        if (centering == PRIMITIVE) {
            if (is_hall_symbol(shift, hall_number, primitive_lattice, symmetry,
                               centering, cubic_generators[i], cubic_VSpU[i],
                               symprec)) {
                goto found;
            }
        }

        if (centering == BODY) {
            if (is_hall_symbol(shift, hall_number, primitive_lattice, symmetry,
                               centering, cubic_generators[i], cubic_I_VSpU[i],
                               symprec)) {
                goto found;
            }
        }

        if (centering == FACE) {
            if (is_hall_symbol(shift, hall_number, primitive_lattice, symmetry,
                               centering, cubic_generators[i], cubic_F_VSpU[i],
                               symprec)) {
                goto found;
            }
        }
    }

    return 0;

found:
    return 1;
}

