                break;
            case A_FACE:
                mat_get_similar_matrix_d3(rot_reduced, rot_reduced, M_ac_inv,
                                          0);
                break;
            case B_FACE:
                mat_get_similar_matrix_d3(rot_reduced, rot_reduced, M_bc_inv,
                                          0);
                break;
            case C_FACE:
                mat_get_similar_matrix_d3(rot_reduced, rot_reduced, M_cc_inv,
                                          0);
                break;
            case R_CENTER:
                mat_get_similar_matrix_d3(rot_reduced, rot_reduced, M_rc_inv,
                                          0);
                break;
            default:
                break;
        }
    }
}

static int get_origin_shift(double shift[3], int const hall_number,
                            int const rot[3][3][3], double const trans[3][3],
                            Centering const centering,
                            double const VSpU[3][9]) {
    int i, j;
    int operation_index[2];
    double dw[9], tmp_dw[3];

    spgdb_get_operation_index(operation_index, hall_number);

    /* The obtained dw is reduced to that of primitive cell by centerings. */
    for (i = 0; i < 3; i++) {
        /* Zero matrix is the sign to set dw 0 */
        if (mat_get_determinant_i3(rot[i]) == 0) {
            for (j = 0; j < 3; j++) {
                dw[i * 3 + j] = 0;
            }
        } else {
            if (set_dw(tmp_dw, operation_index, rot[i], trans[i], centering)) {
                dw[i * 3] = mat_Dmod1(tmp_dw[0]);
                dw[i * 3 + 1] = mat_Dmod1(tmp_dw[1]);
                dw[i * 3 + 2] =
                    hall_number > 0 ? mat_Dmod1(tmp_dw[2]) : tmp_dw[2];
            } else {
                goto not_found;
            }
        }
    }

    /* VSpU*dw is given for the primitive cell if there is centering. */
    for (i = 0; i < 3; i++) {
        shift[i] = 0;
        for (j = 0; j < 9; j++) {
            shift[i] += VSpU[i][j] * dw[j];
        }
    }

    shift[0] = mat_Dmod1(shift[0]);
    shift[1] = mat_Dmod1(shift[1]);
    shift[2] = hall_number > 0 ? mat_Dmod1(shift[2]) : shift[2];

    return 1;

not_found:
    return 0;
}

static int set_dw(double dw[3], int const operation_index[2],
                  int const rot[3][3], double const trans[3],
                  Centering const centering) {
    int i, j;
    int rot_db[3][3];
    double trans_db[3], trans_prim[3], trans_db_prim[3];

    transform_translation(trans_prim, centering, trans);
    for (i = 0; i < operation_index[0]; i++) {
        spgdb_get_operation(rot_db, trans_db, operation_index[1] + i);
        transform_translation(trans_db_prim, centering, trans_db);
        if (mat_check_identity_matrix_i3(rot_db, rot)) {
            for (j = 0; j < 3; j++) {
                dw[j] = trans_prim[j] - trans_db_prim[j];
                /* dw[j] = mat_Dmod1(dw[j]); */
            }
            goto found;
        }
    }

    /* Not found */
    return 0;

found:
    return 1;
}

static int is_match_database(int const hall_number,
                             double const origin_shift[3],
                             double const primitive_lattice[3][3],
                             Centering const centering,
                             Symmetry const *symmetry, double const symprec) {
    int i, j, k, is_found;
    int operation_index[2];
    int rot_db[3][3];
    int found_list[192];
    double trans_db[3], trans_db_prim[3], trans_prim[3], diff[3], shift_rot[3];
    double rot_prim[3][3];
    int periodic_axes[2] = {0, 1};

    spgdb_get_operation_index(operation_index, hall_number);

    for (i = 0; i < symmetry->size; i++) {
        found_list[i] = 0;
    }
    for (i = 0; i < symmetry->size; i++) {
        is_found = 0;
        for (j = 0; j < operation_index[0]; j++) {
            spgdb_get_operation(rot_db, trans_db, operation_index[1] + j);
            if (mat_check_identity_matrix_i3(symmetry->rot[i], rot_db)) {
                transform_translation(trans_db_prim, centering, trans_db);
                transform_translation(trans_prim, centering,
                                      symmetry->trans[i]);
                transform_rotation(rot_prim, centering, rot_db);
                for (k = 0; k < 3; k++) {
                    diff[k] =
                        trans_prim[k] - trans_db_prim[k] + origin_shift[k];
                }
                mat_multiply_matrix_vector_d3(shift_rot, rot_prim,
                                              origin_shift);
                if ((hall_number > 0 &&
                     cel_is_overlap(diff, shift_rot, primitive_lattice,
                                    symprec)) ||
                    (hall_number < 0 &&
                     cel_layer_is_overlap(diff, shift_rot, primitive_lattice,
                                          periodic_axes, symprec))) {
                    if (!found_list[j]) {
                        found_list[j] = 1;
                        is_found = 1;
                        break;
                    }
                }
            }
        }

        if (!is_found) {
            goto not_found;
        }
    }

    return 1;

not_found:
    return 0;
}

static int match_hall_symbol_db(
    double origin_shift[3], double conv_lattice[3][3],
    double const (*orig_lattice)[3], int const hall_number,
    int const pointgroup_number, Holohedry const holohedry,
    Centering const centering, Symmetry const *symmetry, double const symprec) {
    int is_found, num_free_axes;
    SpacegroupType spacegroup_type;
    Symmetry *changed_symmetry;
    double changed_lattice[3][3], inv_lattice[3][3], tmat[3][3];

    changed_symmetry = NULL;

    spacegroup_type = spgdb_get_spacegroup_type(hall_number);

    if (pointgroup_number != spacegroup_type.pointgroup_number) {
        goto err;
    }

    switch (holohedry) {
        case MONOCLI:
            if (match_hall_symbol_db_monocli(
                    origin_shift, conv_lattice, orig_lattice, hall_number,
                    spacegroup_type.number, centering, symmetry, symprec)) {
                return 1;
            }
            break;

        case ORTHO:
            if (hall_number > 0) {
                num_free_axes =
                    num_axis_choices_ortho[spacegroup_type.number - 16];
            } else if (hall_number < 0) {
                num_free_axes =
                    layer_num_axis_choices_ortho[spacegroup_type.number - 19];
            }
            assert(num_free_axes > 0);

            /* Switching two axes */
            /* Two steps: */
            /*   1. Finding principal axis for the representative hall symbol */
            /*      of the specified hall symbol without checking basis vector
             */
            /*      lengths preference. */
            /*   2. Finding transformation matrix and origin shift for the */
            /*      specified hall symbol. */
            if (hall_number > 0 && num_free_axes == 2) {
                mat_copy_matrix_d3(changed_lattice, conv_lattice);
                if (!match_hall_symbol_db_ortho(
                        origin_shift, changed_lattice, orig_lattice,
                        spacegroup_to_hall_number[spacegroup_type.number - 1],
                        centering, symmetry, 0, symprec)) {
                    break;
                }
                mat_inverse_matrix_d3(inv_lattice, conv_lattice, 0);
                mat_multiply_matrix_d3(tmat, inv_lattice, changed_lattice);

                if ((changed_symmetry = get_conventional_symmetry(
                         tmat, PRIMITIVE, symmetry)) == NULL) {
                    goto err;
                }

                is_found = match_hall_symbol_db_ortho(
                    origin_shift, changed_lattice, orig_lattice, hall_number,
                    centering, changed_symmetry, 2, symprec);
                sym_free_symmetry(changed_symmetry);
                changed_symmetry = NULL;
                if (is_found) {
                    mat_copy_matrix_d3(conv_lattice, changed_lattice);
                    return 1;
                }
                break;
            }

            if (match_hall_symbol_db_ortho(origin_shift, conv_lattice,
                                           orig_lattice, hall_number, centering,
                                           symmetry, num_free_axes, symprec)) {
                return 1;
            }
            break;

        case CUBIC:
            if (match_hall_symbol_db_cubic(origin_shift, conv_lattice,
                                           orig_lattice, hall_number, centering,
                                           symmetry, symprec)) {
                return 1;
            }
            break;

        case TRIGO:
            if ((centering == R_CENTER) &&
                (hall_number == 433 || hall_number == 434 ||
                 hall_number == 436 || hall_number == 437 ||
                 hall_number == 444 || hall_number == 445 ||
                 hall_number == 450 || hall_number == 451 ||
                 hall_number == 452 || hall_number == 453 ||
                 hall_number == 458 || hall_number == 459 ||
                 hall_number == 460 || hall_number == 461)) {
                /* Rhombohedral. symmetry is for a=b=c basis. */
                if (match_hall_symbol_db_rhombo(origin_shift, conv_lattice,
                                                orig_lattice, hall_number,
                                                symmetry, symprec)) {
                    return 1;
                }
                break;
            }
            /* Do not break for other trigonal cases */
        default: /* HEXA, TETRA, TRICLI and rest of TRIGO */
            if (match_hall_symbol_db_others(
                    origin_shift, conv_lattice, orig_lattice, hall_number,
                    centering, holohedry, symmetry, symprec)) {
                return 1;
            }
            break;
    }

err:
    return 0;
}

/* Return 0 if failed */
static int match_hall_symbol_db_monocli(
static Symmetry *get_conventional_symmetry(double const tmat[3][3],
                                           Centering const centering,
                                           Symmetry const *primitive_sym) {
    int i, j, k, multi, size;
    double inv_tmat[3][3], shift[3][3];
    double symmetry_rot_d3[3][3], primitive_sym_rot_d3[3][3];
    Symmetry *symmetry;

    symmetry = NULL;

    size = primitive_sym->size;

    switch (centering) {
        case FACE:
            if ((symmetry = sym_alloc_symmetry(size * 4)) == NULL) {
                return NULL;
            }
            break;
        case R_CENTER:
            if ((symmetry = sym_alloc_symmetry(size * 3)) == NULL) {
                return NULL;
            }
            break;
        case BODY:
        case A_FACE:
        case B_FACE:
        case C_FACE:
            if ((symmetry = sym_alloc_symmetry(size * 2)) == NULL) {
                return NULL;
            }
            break;
        default:
            if ((symmetry = sym_alloc_symmetry(size)) == NULL) {
                return NULL;
            }
            break;
    }

    for (i = 0; i < size; i++) {
        mat_cast_matrix_3i_to_3d(primitive_sym_rot_d3, primitive_sym->rot[i]);

        /* C*S*C^-1: recover conventional cell symmetry operation */
        mat_get_similar_matrix_d3(symmetry_rot_d3, primitive_sym_rot_d3, tmat,
                                  0);
        mat_cast_matrix_3d_to_3i(symmetry->rot[i], symmetry_rot_d3);

        /* translation in conventional cell: C = B^-1*P */
        mat_inverse_matrix_d3(inv_tmat, tmat, 0);
        mat_multiply_matrix_vector_d3(symmetry->trans[i], inv_tmat,
                                      primitive_sym->trans[i]);
    }

    multi = 1;

    if (centering != PRIMITIVE) {
        multi = get_centering_shifts(shift, centering);
        for (i = 0; i < multi - 1; i++) {
            for (j = 0; j < size; j++) {
                mat_copy_matrix_i3(symmetry->rot[(i + 1) * size + j],
                                   symmetry->rot[j]);
                for (k = 0; k < 3; k++) {
                    symmetry->trans[(i + 1) * size + j][k] =
                        symmetry->trans[j][k] + shift[i][k];
                }
            }
        }
    }

    /* This is done in get_origin_shift
    for (i = 0; i < multi; i++) {
      for (j = 0; j < size; j++) {
        for (k = 0; k < 3; k++) {
          symmetry->trans[i * size + j][k] =
            mat_Dmod1(symmetry->trans[i * size + j][k]);
        }
      }
    }
    */

    return symmetry;
}

/* Return CENTERING_ERROR if failed */
static Centering get_centering(double correction_mat[3][3],
                               int const tmat[3][3], Laue const laue) {
    int det;
    double trans_corr_mat[3][3];
    Centering centering;

    mat_copy_matrix_d3(correction_mat, identity);
    det = abs(mat_get_determinant_i3(tmat));
    debug_print("laue class: %d\n", laue);
    debug_print("multiplicity: %d\n", det);

    switch (det) {
        case 1:
            centering = PRIMITIVE;
            break;

        case 2:
            centering = get_base_center(tmat);
            if (centering == A_FACE) {
                if (laue == LAUE2M) {
                    debug_print("Monocli A to C\n");
                    mat_copy_matrix_d3(correction_mat, monocli_a2c);
                } else {
                    mat_copy_matrix_d3(correction_mat, a2c);
                }
                centering = C_FACE;
            }
            if (centering == B_FACE) {
                mat_copy_matrix_d3(correction_mat, b2c);
                centering = C_FACE;
            }
            if (laue == LAUE2M && centering == BODY) {
                debug_print("Monocli I to C\n");
                mat_copy_matrix_d3(correction_mat, monocli_i2c);
                centering = C_FACE;
            }
            break;

        case 3:
            /* hP (a=b) but not hR (a=b=c) */
            centering = R_CENTER;
            mat_multiply_matrix_id3(trans_corr_mat, tmat, rhombo_obverse);
            if (mat_is_int_matrix(trans_corr_mat, INT_PREC)) {
                mat_copy_matrix_d3(correction_mat, rhombo_obverse);
                debug_print("R-center observe setting\n");
                debug_print_matrix_d3(trans_corr_mat);
            }
            mat_multiply_matrix_id3(trans_corr_mat, tmat, rhomb_reverse);
            if (mat_is_int_matrix(trans_corr_mat, INT_PREC)) {
                mat_copy_matrix_d3(correction_mat, rhomb_reverse);
                debug_print("R-center reverse setting\n");
                debug_print_matrix_d3(trans_corr_mat);
            }
            break;

        case 4:
            centering = FACE;
            break;

        default:
            centering = CENTERING_ERROR;
            break;
    }

    return centering;
}

static Centering get_base_center(int const tmat[3][3]) {
    int i;
    Centering centering = PRIMITIVE;

    debug_print("lat_get_base_center\n");

    /* C center */
    for (i = 0; i < 3; i++) {
        if (tmat[i][0] == 0 && tmat[i][1] == 0 && abs(tmat[i][2]) == 1) {
            centering = C_FACE;
            goto end;
        }
    }

    /* A center */
    for (i = 0; i < 3; i++) {
        if (abs(tmat[i][0]) == 1 && tmat[i][1] == 0 && tmat[i][2] == 0) {
            centering = A_FACE;
            goto end;
        }
    }

    /* B center */
    for (i = 0; i < 3; i++) {
        if (tmat[i][0] == 0 && abs(tmat[i][1]) == 1 && tmat[i][2] == 0) {
            centering = B_FACE;
            goto end;
        }
    }

    /* body center */
    if ((abs(tmat[0][0]) + abs(tmat[0][1]) + abs(tmat[0][2]) == 2) &&
        (abs(tmat[1][0]) + abs(tmat[1][1]) + abs(tmat[1][2]) == 2) &&
        (abs(tmat[2][0]) + abs(tmat[2][1]) + abs(tmat[2][2]) == 2)) {
        centering = BODY;
        goto end;
    }

    /* This should not happen. */
    warning_print("spglib: No centring was found.\n");
    return PRIMITIVE;

end:
    return centering;
}

static int get_centering_shifts(double shift[3][3], Centering const centering) {
    int i, j, multi;

    multi = 1;
    for (i = 0; i < 3; i++) {
        for (j = 0; j < 3; j++) {
            shift[i][j] = 0;
        }
    }

    if (centering != PRIMITIVE) {
        if (centering != FACE && centering != R_CENTER) {
            for (i = 0; i < 3; i++) {
                shift[0][i] = 0.5;
            } /* BODY */
            if (centering == A_FACE) {
                shift[0][0] = 0;
            }
            if (centering == B_FACE) {
                shift[0][1] = 0;
            }
            if (centering == C_FACE) {
                shift[0][2] = 0;
            }
            multi = 2;
        }

        if (centering == R_CENTER) {
            shift[0][0] = 2. / 3;
            shift[0][1] = 1. / 3;
            shift[0][2] = 1. / 3;
            shift[1][0] = 1. / 3;
            shift[1][1] = 2. / 3;
            shift[1][2] = 2. / 3;
            multi = 3;
        }

        if (centering == FACE) {
            shift[0][0] = 0;
            shift[0][1] = 0.5;
            shift[0][2] = 0.5;
            shift[1][0] = 0.5;
            shift[1][1] = 0;
            shift[1][2] = 0.5;
            shift[2][0] = 0.5;
            shift[2][1] = 0.5;
            shift[2][2] = 0;
            multi = 4;
        }
    }

    return multi;
}

// @brief Return 1 if `lattice` and `orig_lattice` is equivalent.
//        The equivalence is defined though `mode`.
// @param[out] tmat Isometric transformation s.t. orig_lattice = lattice * tmat
// if exists
// @param[in] mode
//            mode=0: Equivalent if `lattice` and `orig_lattice` are identical
//            as matrices. mode=1: Allow to flip axes when abs(P)=I but P!=I.
//            mode=2: Check equivalence from their metric tensors.
// @param[in] lattice
// @param[in] orig_lattice
// @param[in] symprec
static int is_equivalent_lattice(double tmat[3][3], int const mode,
                                 double const lattice[3][3],
                                 double const orig_lattice[3][3],
                                 double const symprec) {
    int i, j;
    double inv_lat[3][3], tmat_abs[3][3], metric[3][3], orig_metric[3][3];
    int tmat_int[3][3];

    if (mat_Dabs(mat_get_determinant_d3(lattice) -
                 mat_get_determinant_d3(orig_lattice)) > symprec) {
        goto fail;
    }

    if (!mat_inverse_matrix_d3(inv_lat, lattice, symprec)) {
        goto fail;
    }

    // orig_lattice == lattice @ tmat
    mat_multiply_matrix_d3(tmat, inv_lat, orig_lattice);

    switch (mode) {
        case 0: /* Check identity of all elements */
            if (mat_check_identity_matrix_d3(identity, tmat, symprec)) {
                return 1;
            }
            break;

        case 1: /* Check identity of all elements allowing axes flips */
            for (i = 0; i < 3; i++) {
                for (j = 0; j < 3; j++) {
                    tmat_abs[i][j] = mat_Dabs(tmat[i][j]);
                }
            }

            if (mat_check_identity_matrix_d3(identity, tmat_abs, symprec)) {
                return 1;
            }
            break;

        case 2: /* Check metric tensors */
            mat_cast_matrix_3d_to_3i(tmat_int, tmat);
            if (!mat_check_identity_matrix_id3(tmat_int, tmat, symprec)) {
                break;
            }
            if (mat_get_determinant_i3(tmat_int) != 1) {
                break;
            }
            mat_get_metric(orig_metric, orig_lattice);
            mat_get_metric(metric, lattice);
            if (mat_check_identity_matrix_d3(orig_metric, metric, symprec)) {
                return 1;
            }
            break;
    }

fail:
    return 0;
}
