    Primitive *primitive;
    Symmetry *reduced_symmetry;

    spacegroup = NULL;
    primitive = NULL;
    reduced_symmetry = NULL;

    if ((primitive = prm_alloc_primitive(1)) == NULL) {
        goto err;
    }
    if ((primitive->cell = cel_alloc_cell(1, NOSPIN)) == NULL) {
        goto err;
    }

    /* The conventional-axis search assumes a reduced primitive basis.
     * Translation reduction alone does not ensure this for supplied
     * operations. With L_red = L_prim * tmat, transform both parts of every
     * operation as (tmat^-1 R tmat, tmat^-1 t). */
    if (!del_delaunay_reduce(primitive->cell->lattice, prim_lat, symprec) ||
        !mat_inverse_matrix_d3(inv_lat, prim_lat, symprec)) {
        goto err;
    }
    mat_multiply_matrix_d3(tmat, inv_lat, primitive->cell->lattice);
    if (!mat_is_int_matrix(tmat, INT_PREC)) {
        goto err;
    }
    mat_cast_matrix_3d_to_3i(tmat_int, tmat);
    if (abs(mat_get_determinant_i3(tmat_int)) != 1) {
        goto err;
    }
    mat_cast_matrix_3i_to_3d(tmat, tmat_int);
    if ((reduced_symmetry =
             get_conventional_symmetry(tmat, PRIMITIVE, symmetry)) == NULL) {
